package com.englishhero.reading.translation;
import com.englishhero.practice.*;import com.englishhero.reading.*;import com.englishhero.identity.*;import com.englishhero.web.BusinessException;import java.util.*;import org.junit.jupiter.api.Test;
import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;
class PracticeSelectionSourceTest {
 final PracticeAttemptService singles=mock(PracticeAttemptService.class);final PracticePaperAttemptService papers=mock(PracticePaperAttemptService.class);final SessionPrincipal actor=mock(SessionPrincipal.class);
 final PracticeSelectionSource source=new PracticeSelectionSource(singles,papers);
 final ReadingDtos.ArticleVersionDto article=new ReadingDtos.ArticleVersionDto("20","10",1,"Reading","阅读","",null,"B1",ArticleContent.normalize("Quiet spaces help people read."),6,1,"Author","ORIGINAL",null,"");
 @Test void singleReadingUsesOwnedAttemptSnapshotAndRejectsMismatchedVersion(){var attempt=mock(PracticeDtos.Attempt.class);when(attempt.article()).thenReturn(article);when(attempt.readingType()).thenReturn("DETAILED");when(attempt.status()).thenReturn("IN_PROGRESS");when(singles.get(actor,"1")).thenReturn(attempt);assertThat(source.resolve(actor,new SelectionTranslationDtos.Input(null,"10","20","Quiet spaces","TRANSLATION","1",null,null))).isEqualTo(article);assertThatThrownBy(()->source.resolve(actor,new SelectionTranslationDtos.Input(null,"10","21","Quiet spaces","TRANSLATION","1",null,null))).isInstanceOf(BusinessException.class);}
 @Test void hiddenListeningAndUnsubmittedPaperCannotTranslate(){var attempt=mock(PracticeDtos.Attempt.class);when(attempt.readingType()).thenReturn("LISTENING");when(attempt.status()).thenReturn("IN_PROGRESS");when(singles.get(actor,"1")).thenReturn(attempt);assertThatThrownBy(()->source.resolve(actor,new SelectionTranslationDtos.Input(null,"10","20","Quiet spaces","TRANSLATION","1",null,null))).isInstanceOfSatisfying(BusinessException.class,e->assertThat(e.status).isEqualTo(409));var paper=mock(PracticePaperDtos.Attempt.class);when(paper.status()).thenReturn("IN_PROGRESS");when(papers.get(actor,"2")).thenReturn(paper);assertThatThrownBy(()->source.resolve(actor,new SelectionTranslationDtos.Input(null,"10","20","Quiet spaces","TRANSLATION",null,"2","DETAILED_1"))).isInstanceOfSatisfying(BusinessException.class,e->assertThat(e.status).isEqualTo(409));}
 @Test void completedPaperOnlyAllowsItsObjectiveReadingSlot(){var a=mock(PracticeDtos.Attempt.class);when(a.article()).thenReturn(article);when(a.readingType()).thenReturn("DETAILED");when(a.status()).thenReturn("COMPLETED");var paper=mock(PracticePaperDtos.Attempt.class);when(paper.status()).thenReturn("COMPLETED");when(paper.components()).thenReturn(List.of(new PracticePaperDtos.ComponentAttempt("DETAILED_1","DETAILED","Reading",a,null,"",0,null,null)));when(papers.get(actor,"2")).thenReturn(paper);assertThat(source.resolve(actor,new SelectionTranslationDtos.Input(null,"10","20","Quiet spaces","TRANSLATION",null,"2","DETAILED_1"))).isEqualTo(article);assertThatThrownBy(()->source.resolve(actor,new SelectionTranslationDtos.Input(null,"10","20","Quiet spaces","TRANSLATION",null,"2","WRITING"))).isInstanceOf(BusinessException.class);}
}
